pub fn add(a: i32, b: i32) -> i32 {
    a + b
}

/// A simple LIFO stack backed by a `Vec`.
///
/// # Examples
///
/// ```
/// use target_lib::Stack;
///
/// let mut stack = Stack::new();
/// assert!(stack.is_empty());
/// stack.push(1);
/// stack.push(2);
/// assert_eq!(stack.pop(), Some(2));
/// assert_eq!(stack.pop(), Some(1));
/// assert_eq!(stack.pop(), None);
/// ```
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct Stack<T> {
    items: Vec<T>,
}

impl<T> Stack<T> {
    /// Creates a new, empty stack.
    pub fn new() -> Self {
        Stack { items: Vec::new() }
    }

    /// Pushes `item` onto the top of the stack.
    pub fn push(&mut self, item: T) {
        self.items.push(item);
    }

    /// Removes and returns the top item, or `None` if the stack is empty.
    pub fn pop(&mut self) -> Option<T> {
        self.items.pop()
    }

    /// Returns `true` if the stack holds no items.
    pub fn is_empty(&self) -> bool {
        self.items.is_empty()
    }

    /// Returns the number of items in the stack.
    pub fn len(&self) -> usize {
        self.items.len()
    }

    /// Returns the top item without removing it, or `None` if empty.
    pub fn peek(&self) -> Option<&T> {
        self.items.last()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_add() {
        assert_eq!(add(2, 3), 5);
    }

    #[test]
    fn new_stack_is_empty() {
        let stack: Stack<i32> = Stack::new();
        assert!(stack.is_empty());
        assert_eq!(stack.len(), 0);
    }

    #[test]
    fn push_makes_stack_non_empty() {
        let mut stack = Stack::new();
        stack.push(42);
        assert!(!stack.is_empty());
        assert_eq!(stack.len(), 1);
    }

    #[test]
    fn pop_returns_items_in_lifo_order() {
        let mut stack = Stack::new();
        stack.push(1);
        stack.push(2);
        stack.push(3);

        assert_eq!(stack.pop(), Some(3));
        assert_eq!(stack.pop(), Some(2));
        assert_eq!(stack.pop(), Some(1));
        assert_eq!(stack.pop(), None);
        assert!(stack.is_empty());
    }

    #[test]
    fn pop_on_empty_stack_returns_none() {
        let mut stack: Stack<String> = Stack::new();
        assert_eq!(stack.pop(), None);
    }

    #[test]
    fn push_after_draining_reuses_stack() {
        let mut stack = Stack::new();
        stack.push("a");
        assert_eq!(stack.pop(), Some("a"));
        assert!(stack.is_empty());

        stack.push("b");
        assert_eq!(stack.len(), 1);
        assert_eq!(stack.pop(), Some("b"));
    }

    #[test]
    fn peek_does_not_remove() {
        let mut stack = Stack::new();
        assert_eq!(stack.peek(), None);

        stack.push(7);
        assert_eq!(stack.peek(), Some(&7));
        assert_eq!(stack.len(), 1);
    }

    #[test]
    fn works_with_non_copy_types() {
        let mut stack = Stack::new();
        stack.push(String::from("hello"));
        stack.push(String::from("world"));

        assert_eq!(stack.pop(), Some(String::from("world")));
        assert_eq!(stack.pop(), Some(String::from("hello")));
        assert!(stack.is_empty());
    }

    #[test]
    fn default_matches_new() {
        let stack: Stack<u8> = Stack::default();
        assert_eq!(stack, Stack::new());
        assert!(stack.is_empty());
    }
}

